              {updateActions.map(renderActionItem)}
            </AccordionDetails>
          </Accordion>
        )}

        {deleteActions.length > 0 && (
          <Accordion>
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              <Typography variant="subtitle2" fontWeight={600}>
                Delete ({deleteActions.length})
              </Typography>
            </AccordionSummary>
