              {deleteActions.map(renderActionItem)}
            </AccordionDetails>
          </Accordion>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} variant="outlined">
          Cancel
        </Button>
        <Button
          onClick={handleExecute}
          variant="contained"
          disabled={preview.conflicts.length > 0 && hasUnresolvedConflicts}
        >
          Execute Sync
        </Button>
      </DialogActions>
    </Dialog>
  );
};

